import{t as e}from"./utils-COoNfFoj.js";var t={slug:`caroline-langdon`,influencerName:`Caroline Langdon`,influencerHandle:`@impactmediahouse`,influencerAvatarUrl:`${e}/caroline-langdon-avatar.png`,heroDescription:`I built this dashboard with Computer to stop guessing what to post. It tracks 20+ creators in my niche, tells me which hooks are actually pulling views, and writes my next week of content from my own data — every week, automatically. Click through each of the tabs and see how you can create a version of your own.`,assetTitle:`Creator Intelligence — Pattern Map`,screenshotUrl:`${e}/caroline-langdon.png`,remixUrl:`https://www.perplexity.ai/computer/a/creatorintel-the-impact-media-JhUIFEPZRc6cbZnww6AftA`,promptTitle:`Try Caroline's prompt`,promptText:`Build me a 48-hour Instagram intelligence dashboard for ~20 creators in my niche. Surface the dominant themes, hook types, and formats from their last 48 hours, flagging which lanes are saturated and which are underused. Deliver as a live HTML site in my brand system, refreshed every 48 hours at the same URL.

Build me a hook performance engine that ranks which opening lines are pulling views in my niche, benchmarked against my account. Score hooks from ~20 creators by engagement, surface this cycle’s winning formulas, then generate 3 high-probability hooks in my voice — each tied to a winning pattern. Deliver as a live HTML section in my brand system, auto-updated and copy-ready.

Build me a weekly Instagram dashboard and 5-post content calendar as a live HTML site plus branded PDF. Each Monday, pull my latest metrics vs. last week, scan 2–3 competitor trends in my niche, and generate a Mon–Fri plan where every post ties to a specific signal — winning hook, underused lane, or metric to fix — with format, hook, outline or reel script, caption, and CTA. Apply my brand system, mix 3 carousels + 1 reel + 1 story, and redeploy at the same URL.`};export{t as default};
